import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";

import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";

function AppRouter() {
  const [incomeCategory, setIncomeCategory] = useState("");
  const [questionnaire, setQuestionnaire] = useState({});
  const [spendingPriorities, setSpendingPriorities] = useState({});

  return (
    <Router>
      <Routes>

        {/* START FROM INCOME CATEGORY */}
        <Route
          path="/"
          element={<Navigate to="/income" />}
        />

        <Route
          path="/income"
          element={
            <IncomeCategory
              onNext={(category) => setIncomeCategory(category)}
            />
          }
        />

        <Route
          path="/questionnaire"
          element={
            <Questionnaire
              onNext={(data) => setQuestionnaire(data)}
            />
          }
        />

        <Route
          path="/spending"
          element={
            <SpendingPriority
              onNext={(data) => setSpendingPriorities(data)}
            />
          }
        />

        <Route
          path="/budget"
          element={
            <BudgetLimits
              spendingPriorities={spendingPriorities || {}}
              incomeCategory={incomeCategory}
              questionnaire={questionnaire}
            />
          }
        />

      </Routes>
    </Router>
  );
}

export default AppRouter;
